    [410123] = { en = "Engrave your gloves with the Explosive Shot rune:\r\n\r\n$@spellicon409552\r\n$@spelldesc409552", description = "Incidi sui guanti la runa Tiro Esplosivo:\r\n\r\n$@spellicon409552\r\n$@spelldesc409552" },
    [411684] = { en = "Charge an enemy, generate $/10;s2 rage, and stun it for $7922d.  ", description = "Carica un nemico, generi $/10;s2 punti rabbia e lo stordisci per $7922d.  " },
    [412096] = { en = "Finishing move that slashes all enemies within $a2 yards, causing victims to Bleed over time. Lasts longer and deals more damage per combo point.\r\n\r\n   1 point  : ${$AP*0.30} damage over 4 sec.\r\n   2 points: ${$AP*0.45} damage over 6 sec.\r\n   3 points: ${$AP*0.60} damage over 8 sec.\r\n   4 points: ${$AP*0.75} damage over 10 sec.\r\n   5 points: ${$AP*0.90} damage over 12 sec.\r\n\r\nCrimson Tempest benefits from all talents and effects that trigger from or modify Rupture.\r\n\r\n", description = "Mossa finale che colpisce tutti i nemici entro $a2 metri, facendo Sanguinare le vittime nel tempo. Dura più a lungo e infligge più danni per ogni punto combo.\r\n\r\n   1 punto  : ${$AP*0.30} danni in 4 sec.\r\n   2 punti: ${$AP*0.45} danni in 6 sec.\r\n   3 punti: ${$AP*0.60} danni in 8 sec.\r\n   4 punti: ${$AP*0.75} danni in 10 sec.\r\n   5 punti: ${$AP*0.90} danni in 12 sec.\r\n\r\nTempesta Cremisi beneficia di tutti i talenti e gli effetti che si attivano con o modificano Lacerare.\r\n\r\n" },
    [412115] = { en = "Your Mana Shield, Frost Ward, and Fire Ward spells can now be cast on any friendly target and absorb $s1% increased damage, with Mana Shield consuming $s2% less mana per damage absorbed. Additionally, your Remove Lesser Curse is replaced with Remove Greater Curse.\r\n\r\n$@spellicon412113\r\n$@spelldesc412113", description = "I tuoi incantesimi Scudo di Mana, Protezione dal Gelo e Protezione dal Fuoco possono ora essere lanciati su qualsiasi bersaglio amico e assorbono $s1% danni aggiuntivi, mentre Scudo di Mana consuma $s2% mana in meno per ogni danno assorbito. Inoltre, Rimuovi Maledizione Minore viene sostituito da Rimuovi Maledizione Maggiore.\r\n\r\n$@spellicon412113\r\n$@spelldesc412113" },
    [412507] = { en = "Rend can now be used in Berserker stance, Rend's damage is increased by $s2%, and Rend deals additional damage equal to $s3% of your Attack Power each time it deals damage.\r\n", description = "Lacerare può ora essere usato in assetto Berserker, i danni di Lacerare sono aumentati del $s2% e Lacerare infligge danni aggiuntivi pari al $s3% della tua Potenza d'Attacco ogni volta che infligge danni.\r\n" },
    [412510] = { en = "Heals all of target player's party members within $a1 yards of target player for ${$<healpower>*$m1/100*3} health over $d and applies Temporal Beacon to each target for ${$400735m3/2} sec.\r\n\r\nTemporal Beacon\r\n$@spellicon400735\r\n$@spelldesc400735", description = "Cura tutti i membri del gruppo del giocatore bersaglio entro $a1 metri dal giocatore bersaglio per ${$<healpower>*$m1/100*3} salute in $d e applica Faro Temporale a ciascun bersaglio per ${$400735m3/2} sec.\r\n\r\nFaro Temporale\r\n$@spellicon400735\r\n$@spelldesc400735" },
    [413301] = { en = "Killing an enemy worth experience or Honor generates ${$413302s1/10} Rage.\r\n", description = "Uccidere un nemico che fornisce esperienza o Onore genera ${$413302s1/10} Furia.\r\n" },
    [413380] = { en = "Heroic Strike, Bloodthirst, and Whirlwind have a $h% chance to make your next Slam within $413399d instant, strike with both melee weapons, and cost no Rage.\r\n", description = "Colpo Eroico, Sete di Sangue e Turbine hanno una probabilità del $h% di rendere istantaneo il prossimo Schianto entro $413399d, di colpire con entrambe le armi da mischia e di non costare Furia.\r\n" },
    [413548] = { en = "Degreelessness enabled. Immune to all CC.\r\nFatal damage is absorbed.\r\n$s2% Health healed every $t2 sec.", description = "Grado di gravità abilitato. Immunità a tutti gli effetti di controllo.\r\nI danni letali vengono assorbiti.\r\nIl $s2% della salute viene ripristinato ogni $t2 sec." },
    [414689] = { en = "Burns the enemy for ${$m2*$<damagepower>/100} to ${$M2*$<damagepower>/100} Nature damage and then an additional ${$m1*4*$<damagepower>/100} Nature damage over $d. Awards $s3 combo $lpoint:points;.\r\n", description = "Brucia il nemico infliggendo da ${$m2*$<damagepower>/100} a ${$M2*$<damagepower>/100} danni Natura, poi infligge altri ${$m1*4*$<damagepower>/100} danni Natura in $d. Fornisce $s3 $lpunto:punti combo;.\r\n" },
    [414692] = { en = "Gain the Sunfire ability and while in Bear Form, Cat Form, or Dire Bear Form your Moonfire is replaced with Sunfire (Bear) or Sunfire (Cat). This spell benefits from and triggers all effects associated with Moonfire.\r\n\r\n$@spellicon414684\r\n$@spelldesc414684\r\n\r\n$@spellicon414687\r\n$@spelldesc414687\r\n\r\n$@spellicon414689\r\n$@spelldesc414689\r\n", description = "Ottieni l'abilità Fuoco Solare e, in Forma d'Orso, Forma di Felino o Forma d'Orso Feroce, il tuo Fuoco Lunare viene sostituito da Fuoco Solare (Orso) o Fuoco Solare (Felino). Questo incantesimo beneficia di tutti gli effetti associati a Fuoco Lunare e li attiva.\r\n\r\n$@spellicon414684\r\n$@spelldesc414684\r\n\r\n$@spellicon414687\r\n$@spelldesc414687\r\n\r\n$@spellicon414689\r\n$@spelldesc414689\r\n" },
    [414719] = { en = "Some of your spells and abilities extend the duration of your damage and healing over time effects on their target:\r\n\r\nStarfire extends Moonfire by $s1 sec.\r\nWrath extends Sunfire by $s2 sec.\r\nRegrowth extends Rejuvenation by $s3 sec.\r\nShred extends Rip by $s4 sec.\r\n\r\nEach effect can only be extended up to its initial duration.\r\n", description = "Alcuni dei tuoi incantesimi e abilità estendono la durata degli effetti periodici di danno e guarigione sui bersagli:\r\n\r\nFuoco Stellare estende Fuoco Lunare di $s1 sec.\r\nIra estende Fuoco Solare di $s2 sec.\r\nRicrescita estende Rinvigorimento di $s3 sec.\r\nSventramento estende Lacerare di $s4 sec.\r\n\r\nOgni effetto può essere esteso solo fino alla sua durata iniziale.\r\n" },
    [415292] = { en = "Heals ${$m1/100*$<healpower>*4} over $d sec.\r\n\r\n", description = "Ripristina ${$m1/100*$<healpower>*4} salute in $d sec.\r\n\r\n" },
    [415405] = { en = "Reduces the cooldown on your Rapid Fire ability by ${$m1/-60000} min. In addition, when you kill a non-trivial enemy or it dies while afflicted by your Serpent Sting, you gain Rapid Killing, increasing the damage of your next Shot ability within $415407d by $m2%.", description = "Riduce il tempo di recupero della tua abilità Fuoco Rapido di ${$m1/-60000} min. Inoltre, quando uccidi un nemico non banale o questo muore mentre è affetto dal tuo Pungiglione del Serpente, ottieni Uccisione Rapida, che aumenta del $m2% i danni della prossima abilità di Tiro entro $415407d." },
    [415452] = { en = "Gain the Improved Swipe ability:\r\n\r\n$@spellicon439510\r\n$@spelldesc439510", description = "Ottieni l'abilità Mulinello Migliorato:\r\n\r\n$@spellicon439510\r\n$@spelldesc439510" },
    [415457] = { en = "Gain the Fan of Knives ability:\r\n\r\n$@spellicon409240\r\n$@spelldesc409240", description = "Ottieni l'abilità Ventaglio di Lame:\r\n\r\n$@spellicon409240\r\n$@spelldesc409240" },
