    [416044] = { en = "Engrave your gloves with the Sunfire rune:\r\n\r\n$@spellicon414684\r\n$@spelldesc414684\r\n\r\nIn addition, while in Bear Form, Cat Form, or Dire Bear Form, your Moonfire is replaced with Sunfire (Bear) or Sunfire (Cat). This spell benefits from and triggers all effects associated with Moonfire.\r\n\r\nSunfire (Bear)\r\n$@spelldesc414687\r\n\r\nSunfire (Cat)\r\n$@spelldesc414689", description = "Incidi i tuoi guanti con la runa Fuoco solare:\r\n\r\n$@spellicon414684\r\n$@spelldesc414684\r\n\r\nInoltre, in Forma d'orso, Forma felina o Forma d'orso feroce, il tuo Fuoco lunare viene sostituito da Fuoco solare (orso) o Fuoco solare (felino). Questo incantesimo beneficia di e attiva tutti gli effetti associati a Fuoco lunare.\r\n\r\nFuoco solare (orso)\r\n$@spelldesc414687\r\n\r\nFuoco solare (felino)\r\n$@spelldesc414689" },
