    [417141] = { en = "$?a5487|a9634|a3025[|CFFFFFFFFReuires Cat Form, Bear Form, Dire Bear Form|R][|CFFFF2020Requires Cat Form, Bear Form, Dire Bear Form|R]\r\nCauses your Primal Bite ability to strike up to $s3 targets, removes its cooldown, and increases the critical strike chance of your Combo Point-generating abilities by $s1%. Clears and grants immunity to Fear effects for the duration. Lasts $d.", description = "$?a5487|a9634|a3025[|CFFFFFFFFRichiede Forma felina, Forma d'orso, Forma d'orso feroce|R][|CFFFF2020Richiede Forma felina, Forma d'orso, Forma d'orso feroce|R]\r\nFa sì che la tua abilità Morso primordiale colpisca fino a $s3 bersagli, ne rimuove il tempo di recupero e aumenta del $s1% la probabilità di colpo critico delle tue abilità che generano punti combo. Dissipa gli effetti di paura e fornisce immunità a essi per tutta la durata. Dura $d." },
    [417157] = { en = "Launch surging stellar energies that cause ${$m1/100*$<damagepower>} to ${$M1/100*$<damagepower>} Arcane damage, and increases the damage done by your next $n Starfire $Lcast:casts; by $s2% for $d.\r\n\r\nStarsurge benefits from and triggers most talents and effects that trigger or benefit from Wrath or Starfire.", description = "Scatena energie astrali impetuose che infliggono da ${$m1/100*$<damagepower>} a ${$M1/100*$<damagepower>} danni arcani e aumentano del $s2% i danni inflitti dal tuo prossimo lancio di $n Fuoco stellare $Lcast:lanci; per $d.\r\n\r\nPioggia di stelle beneficia della maggior parte dei talenti e degli effetti che si attivano con Ira o Fuoco stellare o ne traggono beneficio." },
    [417159] = { en = "Instantly heal yourself for $s1% of you maximum health. Useable in all forms.\r\n", description = "Cura istantaneamente te stesso del $s1% della tua salute massima. Utilizzabile in tutte le forme.\r\n" },
    [417453] = { en = "Gain several new demonic abilities: Disrupt, Demon Charge, Demonic Howl, and Infernal Strike.\r\n\r\n$@spellicon412787\r\n$@spelldesc412787\r\n\r\n$@spellicon412788\r\n$@spelldesc412788\r\n\r\n$@spellicon412789\r\n$@spelldesc412789\r\n\r\n$@spellicon412790\r\n$@spelldesc412790", description = "Ottieni diverse nuove abilità demoniache: Interrompere, Carica demoniaca, Ululato demoniaco e Assalto infernale.\r\n\r\n$@spellicon412787\r\n$@spelldesc412787\r\n\r\n$@spellicon412788\r\n$@spelldesc412788\r\n\r\n$@spellicon412789\r\n$@spelldesc412789\r\n\r\n$@spellicon412790\r\n$@spelldesc412790" },
