    [424760] = { en = "Engrave your belt with the Berserk rune:\r\n\r\n$@spellicon417141\r\n$@spelldesc417141", description = "Incidi la runa Berserk sulla tua cintura:\r\n\r\n$@spellicon417141\r\n$@spelldesc417141" },
    [424762] = { en = "Gain the King of the Jungle ability:\r\n\r\n$@spellicon417046\r\n$@spelldesc417046", description = "Ottieni l'abilità Re della giungla:\r\n\r\n$@spellicon417046\r\n$@spelldesc417046" },
