    [424800] = { en = "Instantly attack with your off-hand weapon with a 100% chance to apply the poison from your off-hand weapon to the target. Slower weapons require more energy. Awards $s2 combo $lpoint:points;.\r\n", description = "Attacca istantaneamente con l'arma nella mano secondaria con una probabilità del 100% di applicare al bersaglio il veleno della tua arma nella mano secondaria. Le armi più lente richiedono più energia. Fornisce $s2 $lpunto:punti combo;.\r\n" },
    [424919] = { en = "Instantly strike with your off-hand weapon for normal off-hand weapon damage and increase your chance to parry by $s2% for $d or until you successfully parry. For $462752d after using Main Gauche, Sinister Strike costs $462752s1 less Energy, deals $462752s2% more threat, grants stacks of Rolling with the Punches, and both Sinister Strike and Eviscerate deal $462752s3% more damage. Awards $s3 combo $lpoint:points;.\r\n\r\nMain Gauche benefits from most talents and effects that trigger from or modify Sinister Strike. Main Gauche's effect will not discount or empower Main Gauche.", description = "Colpisci istantaneamente con l'arma nella mano secondaria, infliggendo i normali danni dell'arma nella mano secondaria e aumentando la tua probabilità di parare del $s2% per $d o finché non pari con successo. Per $462752d dopo aver usato Main Gauche, Colpo sinistro costa $462752s1 energia in meno, genera il $462752s2% di minaccia in più, conferisce accumuli di Incassare i colpi e sia Colpo sinistro che Eviscerazione infliggono il $462752s3% di danni in più. Fornisce $s3 $lpunto:punti combo;.\r\n\r\nMain Gauche beneficia della maggior parte dei talenti e degli effetti che si attivano con o modificano Colpo sinistro. L'effetto di Main Gauche non riduce il costo né potenzia Main Gauche." },
    [424925] = { en = "Reduces the Energy cost of your Backstab and Ambush abilities by $s1, and increases the damage they deal to non-player controlled targets by $s2%. $?s400094[Does not apply to Mutilate.][Does not apply to abilities learned from other runes.]", description = "Riduce di $s1 il costo in energia delle tue abilità Agguato e Imboscata e aumenta del $s2% i danni che infliggono ai bersagli non controllati dai giocatori. $?s400094[Non si applica a Mutilazione.][Non si applica alle abilità apprese da altre rune.]" },
