    [425012] = { en = "Instantly throw your off-hand weapon to deal normal off-hand weapon damage with a 100% chance to apply the poison from your off-hand weapon to the target. Awards $s2 combo $lpoint:points;. Refunds $s3 Energy per application of Deadly Poison on the target.\r\n\r\nPoisoned Knife benefits from all talents and effects that trigger from or modify Sinister Strike.\r\n", description = "Lancia istantaneamente l'arma nella mano secondaria, infliggendo i normali danni dell'arma nella mano secondaria con una probabilità del 100% di applicare al bersaglio il veleno della tua arma nella mano secondaria. Fornisce $s2 $lpunto:punti combo;. Restituisce $s3 energia per ogni applicazione di Veleno mortale sul bersaglio.\r\n\r\nColtello avvelenato beneficia di tutti i talenti e gli effetti che si attivano con o modificano Colpo sinistro.\r\n" },
    [425013] = { en = "Instantly throw your off-hand weapon to deal normal off-hand weapon damage with a 100% chance to apply the poison from your off-hand weapon to the target. Awards $s2 combo $lpoint:points;.\r\n\r\nPoisoned Knife benefits from all talents and effects that trigger from or modify Sinister Strike.\r\n\r\n", description = "Lancia istantaneamente l'arma nella mano secondaria, infliggendo i normali danni dell'arma nella mano secondaria con una probabilità del 100% di applicare al bersaglio il veleno della tua arma nella mano secondaria. Fornisce $s2 $lpunto:punti combo;.\r\n\r\nColtello avvelenato beneficia di tutti i talenti e gli effetti che si attivano con o modificano Colpo sinistro.\r\n\r\n" },
