    [425266] = { en = "Your Renew now heals one extra time immediately when applied, and gains $s1% increased benefit each time it heals from your bonus healing effects.\r\n\r\nIn addition, your Renew can now be active on targets affected by another Priest's Renew.\r\n", description = "Rinnovamento ora cura un'ulteriore volta immediatamente quando viene applicato e ottiene un beneficio aumentato del $s1% ogni volta che cura grazie ai tuoi effetti di guarigione bonus.\r\n\r\nInoltre, Rinnovamento può ora essere attivo su bersagli influenzati dal Rinnovamento di un altro Sacerdote.\r\n" },
