    [425412] = { en = "While wielding 2-handed weapons, your attack speed is increased by $s1% and your successful melee hits generate $s2 additional Rage, or ${$m2*2} additional Rage if they are critical hits.\r\n", description = "Quando impugni armi a due mani, la tua velocità d'attacco aumenta del $s1% e i tuoi colpi in mischia a segno generano $s2 punti Rabbia aggiuntivi, oppure ${$m2*2} punti Rabbia aggiuntivi se sono colpi critici.\r\n" },
