    [425600] = { en = "The Paladin blows the Horn of Lordaeron, which increases total Strength and Agility of all party members within $a1 yards by $?s25291[89][${$cond($gte($PL,56),74,$cond($gte($PL,52),60,$cond($gte($PL,42),45,$cond($gte($PL,32),26,$cond($gte($PL,22),17,$cond($gte($PL,12),11,6)))))))}]. Lasts $d. Exclusive with Blessing of Might.", description = "Il Paladino suona il Corno di Lordaeron, aumentando Forza e Agilità totali di tutti i membri del gruppo entro $a1 metri di $?s25291[89][${$cond($gte($PL,56),74,$cond($gte($PL,52),60,$cond($gte($PL,42),45,$cond($gte($PL,32),26,$cond($gte($PL,22),17,$cond($gte($PL,12),11,6)))))))}]. Dura $d. Esclusivo con Benedizione della Potenza." },
