    [426490] = { en = "Let loose a rallying cry, granting all party and raid members within $a1 yards $s1% increased maximum health for $d.", description = "Lancia un grido di battaglia, aumentando del $s1% la salute massima di tutti i membri del gruppo e dell'incursione entro $a1 metri per $d." },
    [426491] = { en = "Engrave your boots with the Rallying Cry rune:\r\n\r\n$@spellicon426490\r\n$@spelldesc426490", description = "Incidi sui tuoi stivali la runa Grido di battaglia:\r\n\r\n$@spellicon426490\r\n$@spelldesc426490" },
    [426492] = { en = "Gain the Rallying Cry ability:\r\n\r\n$@spellicon426490\r\n$@spelldesc426490", description = "Ottieni l'abilità Grido di battaglia:\r\n\r\n$@spellicon426490\r\n$@spelldesc426490" },
    [426953] = { en = "Whenever your Rend ability causes damage, your Overpower ability will activate for $426969d or 1 attack.  This effect will not occur more than once every $s1 sec.", description = "Ogni volta che la tua abilità Lacerazione infligge danni, la tua abilità Sopraffazione si attiva per $426969d o per 1 attacco. Questo effetto non può verificarsi più di una volta ogni $s1 sec." },
    [426972] = { en = "Focus your protective gaze on a party or raid member, reducing their damage taken by $s1% and transferring $m2% of the threat they cause to you.  In addition, each time they are hit by an attack your Taunt cooldown is refreshed.  Lasts $d.  This effect can only be on one target at a time.", description = "Concentra il tuo sguardo protettivo su un membro del gruppo o dell'incursione, riducendo i danni che subisce del $s1% e trasferendo a te il $m2% della minaccia che genera. Inoltre, ogni volta che viene colpito da un attacco, il tempo di recupero della tua Provocazione si azzera. Dura $d. Questo effetto può essere attivo su un solo bersaglio alla volta." },
    [426978] = { en = "When your Devastate and Revenge abilities deal damage they have a $h% chance of refreshing the cooldown of your Shield Slam ability and reducing its Rage cost by $426979s1% for $426979d.", description = "Quando le tue abilità Devastazione e Vendetta infliggono danni, hanno una probabilità del $h% di azzerare il tempo di recupero della tua abilità Schianto con lo Scudo e ridurne il costo in Rabbia del $426979s1% per $426979d." },
    [426980] = { en = "Increases all physical damage you deal by $426981s1% while you have a shield equipped, and reduces the duration of all Disarm effects used against you by $s2%.  This does not stack with other Disarm duration reducing effects.\r\n", description = "Aumenta tutti i danni fisici che infliggi del $426981s1% mentre hai uno scudo equipaggiato e riduce la durata di tutti gli effetti di Disarmo usati contro di te del $s2%. Questo effetto non si cumula con altri effetti che riducono la durata di Disarmo.\r\n" },
    [426981] = { en = "\r\n\r\n", description = "\r\n\r\n" },
    [427020] = { en = "Add $q2 Copper Bars to complete the shipment.", description = "Aggiungi $q2 barre di rame per completare la spedizione." },
    [427065] = { en = "Your melee critical hits Enrage you (activating abilities which require being Enraged), and increase Mortal Strike, Bloodthirst, and Shield Slam damage by $427066s1% for $427066d.", description = "I tuoi colpi critici in mischia ti fanno Infuriare (attivando le abilità che richiedono di essere Infuriati) e aumentano i danni di Colpo mortale, Sete di sangue e Schianto con lo Scudo del $427066s1% per $427066d." },
