    [427081] = { en = "Engrave your bracers with the Rampage rune:\r\n\r\n$@spellicon426940\r\n$@spelldesc426940", description = "Incidi sui tuoi bracciali la runa Furia:\r\n\r\n$@spellicon426940\r\n$@spelldesc426940" },
    [427082] = { en = "Engrave your bracers with the Sword and Board rune:\r\n\r\n$@spellicon426978\r\n$@spelldesc426978", description = "Incidi sui tuoi bracciali la runa Spada e Scudo:\r\n\r\n$@spellicon426978\r\n$@spelldesc426978" },
    [427084] = { en = "Engrave your bracers with the Wrecking Crew rune:\r\n\r\n$@spellicon427065\r\n$@spelldesc427065", description = "Incidi sui tuoi bracciali la runa Squadra demolitrice:\r\n\r\n$@spellicon427065\r\n$@spelldesc427065" },
    [427144] = { en = "This item is infused with the raw power of the Void. When the bearer is attacked this item has a high chance of inflicting a terrible curse, causing the attacker to take additional damage from all sources for 15 seconds. \r\n", description = "Questo oggetto è intriso del potere primordiale del Vuoto. Quando il portatore viene attaccato, l'oggetto ha un'alta probabilità di infliggere una terribile maledizione, che fa subire all'attaccante danni aggiuntivi da tutte le fonti per 15 secondi. \r\n" },
    [427712] = { en = "Increases the critical strike damage bonus of your Corruption, Bane of Agony, Bane of Doom, Drain Soul, Drain Life, Siphon Life, and Wrack spells by $m1%.", description = "Aumenta del $m1% il bonus ai danni da colpo critico dei tuoi incantesimi Corruzione, Maledizione dell'Agonia, Maledizione del Destino, Risucchio dell'Anima, Risucchio della Vita, Sottrazione della Vita e Frustata." },
    [427713] = { en = "Your Conflagrate ability also grants $427714s1% spellcasting haste for $427714d and no longer consumes Immolate.", description = "La tua abilità Conflagrazione fornisce anche il $427714s1% di celerità nel lancio degli incantesimi per $427714d e non consuma più Immolazione." },
    [427744] = { en = "A sweeping attack that does the Felguard's weapon damage plus $s1 to the target and his nearest ally.", description = "Un attacco ad ampio raggio che infligge al bersaglio e al suo alleato più vicino danni pari ai danni dell'arma del Vilguardiano più $s1." },
    [427745] = { en = "Charge an enemy, causing $427746s2 damage and stunning it for $427746d.", description = "Carica un nemico, infliggendo $427746s2 danni e stordendolo per $427746d." },
    [428489] = { en = "Momentarily enter another plane of existence, instantly reducing threat as well as reducing all damage taken and damage dealt by $M% for $d. ", description = "Entri per un istante in un altro piano d'esistenza, riducendo istantaneamente la minaccia e riducendo del $M% tutti i danni subiti e inflitti per $d. " },
    [428491] = { en = "Your Devotion Aura also reduces all spell damage taken by $s1%. ", description = "La tua Aura di Devozione riduce anche tutti i danni da incantesimo subiti del $s1%. " },
    [428708] = { en = "Converts resources into health every second for $d. Up to $s1 Rage, $s2 Energy, or $s3% base Mana is converted per second into up to $s4% health.", description = "Converte risorse in salute ogni secondo per $d. Fino a $s1 Rabbia, $s2 Energia o $s3% del Mana base vengono convertiti ogni secondo in un massimo del $s4% di salute." },
    [428713] = { en = "The target's skin becomes as tough as bark. Physical damage taken is reduced by $s2%.  While protected, damaging attacks will not cause spellcasting delays. Lasts $d.", description = "La pelle del bersaglio diventa resistente come la corteccia. I danni fisici subiti sono ridotti del $s2%. Finché è protetto, gli attacchi che infliggono danni non causano ritardi nel lancio degli incantesimi. Dura $d." },
    [428717] = { en = "Increases the damage done by Explosive Shot and all your damaging traps by $s1%. Additionally, the initial damage of Explosive Trap and the total periodic damage of your Immolation Trap are increased by $s3% of your melee or ranged Attack Power.", description = "Aumenta del $s1% i danni inflitti da Tiro esplosivo e da tutte le tue trappole che infliggono danni. Inoltre, i danni iniziali di Trappola esplosiva e i danni periodici totali di Trappola immolante aumentano di una quantità pari al $s3% della tua potenza d'attacco in mischia o a distanza." },
    [428738] = { en = "Increases the magnitude of your Mana Shield, Frost Ward, and Fire Ward by $s1%, and decreases mana drained by Mana Shield by $s2% per damage done.", description = "Aumenta del $s1% l'entità di Scudo di Mana, Egida di Gelo ed Egida di Fuoco e riduce il Mana prosciugato da Scudo di Mana del $s2% per ogni danno inflitto." },
    [428739] = { en = "Stuns the target for $d.  Only usable on Frozen targets.  Deals ${$428917m1*$<power>/100*$<frostdamage>} to ${$428917M1*$<power>/100*$<frostdamage>} damage to targets permanently immune to Stun. This damage benefits from, but does not consume, stacks of Glaciate.", description = "Stordisce il bersaglio per $d. Utilizzabile solo sui bersagli congelati. Infligge da ${$428917m1*$<power>/100*$<frostdamage>} a ${$428917M1*$<power>/100*$<frostdamage>} danni ai bersagli permanentemente immuni allo stordimento. Questo danno beneficia delle cariche di Glaciazione, ma non le consuma." },
    [428741] = { en = "Causes ${$428743m1/100*$<power>} Fire damage when hit, increases your spell critical strike chance by $s3%, and reduces the chance you are critically hit by $s2%.  Only one type of Armor spell can be active on the Mage at any time.  Lasts $d.", description = "Infligge ${$428743m1/100*$<power>} danni da fuoco quando vieni colpito, aumenta la probabilità di critico dei tuoi incantesimi del $s3% e riduce del $s2% la probabilità di subire colpi critici. Sul Mago può essere attivo un solo tipo di incantesimo Armatura alla volta. Dura $d." },
