    [428861] = { en = "Teleports back to where you last cast Blink from and resets the cooldown on Blink. Only usable within $428865d of casting Blink.", description = "Teletrasporta nel punto da cui hai lanciato Blink l'ultima volta e azzera il tempo di recupero di Blink. Utilizzabile solo entro $428865d dal lancio di Blink." },
    [428863] = { en = "Gain the Displacement ability:\r\n\r\n$@spellicon428861\r\n$@spelldesc428861", description = "Ottieni l'abilità Displacement:\r\n\r\n$@spellicon428861\r\n$@spelldesc428861" },
    [428885] = { en = "Launches an orb of temporal energy which slowly moves forward and every $428888t1 sec grants all nearby party members a shield absorbing ${$428895m1*$<power>/100} damage for $428895d. This shield accumulates additional value if party members remain near the orb.", description = "Lancia una sfera di energia temporale che avanza lentamente e ogni $428888t1 sec fornisce a tutti i membri del gruppo vicini uno scudo che assorbe ${$428895m1*$<power>/100} danni per $428895d. Questo scudo accumula valore aggiuntivo se i membri del gruppo restano vicino alla sfera." },
    [428909] = { en = "Your Holy Light spell reduces the cast time of your next Holy Light spell by ${$428912m1/-1000}.1 sec. Lasts $428912d.", description = "La tua magia Holy Light riduce di ${$428912m1/-1000}.1 sec il tempo di lancio della tua prossima magia Holy Light. Dura $428912d." },
    [428912] = { en = "\r\n\r\n", description = "\r\n\r\n" },
    [429125] = { en = "Hastens your spellcasting, increasing spell casting speed by $s1% and reduces the pushback suffered from damaging attacks while casting by $s2%.  Lasts $d.", description = "Accelera il lancio delle tue magie, aumentando la velocità di lancio del $s1% e riducendo del $s2% l'interruzione causata dagli attacchi che infliggono danni mentre stai lanciando una magia. Dura $d." },
    [429133] = { en = "Increases the damage prevented by your Blessing of Sanctuary by $s1%, and increases damage done by your Blessing of Sanctuary by $s2% of your shield block value.", description = "Aumenta del $s1% i danni impediti dalla tua Blessing of Sanctuary e aumenta i danni inflitti dalla tua Blessing of Sanctuary di una quantità pari al $s2% del tuo valore di blocco dello scudo." },
    [429139] = { en = "Your Consecration damage can now be critical strikes, and damage from your Exorcism, Holy Shock, Sunlight, Holy Wrath, and Consecration spells gains additional critical strike chance equal to your melee critical strike chance.", description = "I danni di Consecration possono ora essere colpi critici e i danni delle magie Exorcism, Holy Shock, Sunlight, Holy Wrath e Consecration ottengono una probabilità aggiuntiva di colpo critico pari alla tua probabilità di colpo critico in mischia." },
    [429142] = { en = "Increases your critical strike chance with spells by $s1%. In addition, your critical healing spells heal the target for $s2% of the healed amount over $426162d.", description = "Aumenta del $s1% la probabilità di colpo critico delle tue magie. Inoltre, le tue magie di cura critiche curano il bersaglio per una quantità pari al $s2% delle cure effettuate nell'arco di $426162d." },
    [429144] = { en = "Reduces the mana cost of your Cleanse and Purify spells by $m1% and reduces the cooldown of your Exorcism and Holy Wrath spells by $m2%.", description = "Riduce del $m1% il costo in mana delle magie Cleanse e Purify e riduce del $m2% il tempo di recupero delle magie Exorcism e Holy Wrath." },
    [429151] = { en = "Hurls a hammer that strikes an enemy for ${$m1*$<damagepower>+0.15*$SPH+0.15*$AP} to ${$M1*$<damagepower>+0.15*$SPH+0.15*$AP} Holy damage.  Only usable on enemies that have 20% or less health.", description = "Scaglia un martello che colpisce un nemico e infligge da ${$m1*$<damagepower>+0.15*$SPH+0.15*$AP} a ${$M1*$<damagepower>+0.15*$SPH+0.15*$AP} danni da Holy. Utilizzabile solo contro nemici con il 20% o meno di salute." },
    [429152] = { en = "Hammer of Wrath is now instant and the cooldown on Hammer of Wrath is reset each time it damages an enemy below $s1% health.", description = "Hammer of Wrath è ora istantaneo e il suo tempo di recupero si azzera ogni volta che infligge danni a un nemico con meno del $s1% di salute." },
    [429242] = { en = "Engrave your bracers with the Light's Grace rune:\r\n\r\n$@spellicon428909\r\n$@spelldesc428909", description = "Incidi le tue bracciali con la runa Light's Grace:\r\n\r\n$@spellicon428909\r\n$@spelldesc428909" },
