    [429748] = { en = "Replaces your Heroic Strike ability with Quick Strike:\r\n\r\n$@spellicon429765\r\n$@spelldesc429765\r\n", description = "Sostituisce l'abilità Heroic Strike con Quick Strike:\r\n\r\n$@spellicon429765\r\n$@spelldesc429765\r\n" },
    [429765] = { en = "A reckless instant melee attack with your two-handed weapon dealing ${$AP*$m1/100} to ${$AP*$M1/100} physical damage. This ability benefits from and triggers all effects associated with Heroic Strike.\r\n\r\n\r\n", description = "Un attacco in mischia istantaneo e sconsiderato con la tua arma a due mani che infligge da ${$AP*$m1/100} a ${$AP*$M1/100} danni fisici. Questa abilità beneficia di tutti gli effetti associati a Heroic Strike e li attiva.\r\n\r\n\r\n" },
    [429864] = { en = "Increases your Strength by $s. ", description = "Aumenta la tua Forza di $s. " },
    [429867] = { en = "Descend into madness, increasing attack speed by $M% as well as increasing the threat you generate for $d. ", description = "Ti abbandoni alla follia, aumentando la velocità d'attacco del $M% e la minaccia generata per $d. " },
    [429868] = { en = "Descend into madness, increasing spell damage by $M% as well as increasing the threat you generate for $d. ", description = "Ti abbandoni alla follia, aumentando i danni magici del $M% e la minaccia generata per $d. " },
    [429959] = { en = "Experience gains increased by $429959s0%. ", description = "Esperienza ottenuta aumentata del $429959s0%. " },
    [429961] = { en = "Unfurl a sleeping bag. Resting inside for at least one minute will provide a bonus to experience earned, stacking up to 3 times.", description = "Apri un sacco a pelo. Riposare al suo interno per almeno un minuto fornisce un bonus all'esperienza ottenuta, cumulabile fino a 3 volte." },
