    [430432] = { en = "Reduces all damage taken and chance to be critically hit by $s1% in Warsong Gulch.", description = "Riduce tutti i danni subiti e la probabilità di subire colpi critici del $s1% a Warsong Gulch." },
    [430472] = { en = "\r\n\r\n", description = "\r\n\r\n" },
    [430496] = { en = "You feel inspired! Experience gains increased by $s1%.", description = "Ti senti ispirato! L'esperienza ottenuta aumenta del $s1%." },
    [430585] = { en = "While applied to the target weapon restores 12 mana per 5 sec and Increases Spell Hit by 2% for $t1 minutes. This effect only applies within Blackfathom Deeps.\r\n", description = "Quando viene applicato all'arma del bersaglio, ripristina 12 mana ogni 5 s e aumenta di 2% la probabilità di colpire con gli incantesimi per $t1 minuti. Questo effetto si applica solo all'interno di Blackfathom Deeps.\r\n" },
