    [430776] = { en = "Add $q2 Elixir of Firepower to complete the shipment.", description = "Aggiungi $q2 Elisir della potenza di fuoco per completare la spedizione." },
    [431046] = { en = "While wielding 2-handed weapons, your attack speed is increased by $s1%.\r\n", description = "Quando impugni armi a due mani, la tua velocità d'attacco aumenta del $s1%.\r\n" },
    [431111] = { en = "Increases hit chance of spells by 3%, critical chance of melee, and ranged by 2%, grants 20 attack power, 25 spell damage, and increases movement speed by 20%. 120 minute duration.\r\n", description = "Aumenta del 3% la probabilità di colpire con gli incantesimi, del 2% la probabilità di critico in mischia e a distanza, fornisce 20 potenza d'attacco e 25 danni magici e aumenta la velocità di movimento del 20%. Dura 120 minuti.\r\n" },
    [431389] = { en = "Your Frenzied Regeneration can now be used in all forms except Moonkin Form or while not shapeshifted. It now converts your active resource into health every second for $428708d. Up to $428708s1 Rage, $428708s2 Energy, or $428708s3% base Mana is converted per second into up to $428708s4% health.\r\n", description = "La tua Rigenerazione Frenetica può ora essere usata in tutte le forme, tranne Forma Lunagufo, o quando non sei in forma mutata. Ora converte ogni secondo la tua risorsa attiva in salute per $428708d. Fino a $428708s1 Rabbia, $428708s2 Energia o $428708s3% del mana base vengono convertiti ogni secondo in fino al $428708s4% di salute.\r\n" },
    [431446] = { en = "Gain the Gore ability:\r\n\r\n$@spellicon417145\r\n$@spelldesc417145", description = "Ottieni l'abilità Gore:\r\n\r\n$@spellicon417145\r\n$@spelldesc417145" },
