    [431655] = { en = "Blasts the target for ${$m1*$<damagepower>/100} to ${$M1*$<damagepower>/100} Shadowfrost damage, and increases the critical strike chance of your next Mind Blast on the target by $s2%, stacking up to $u times.", description = "Colpisce il bersaglio infliggendo da ${$m1*$<damagepower>/100} a ${$M1*$<damagepower>/100} danni da Geloombra e aumenta del $s2% la probabilità di colpo critico del tuo prossimo Colpo Mentale sul bersaglio. L'effetto si accumula fino a $u volte." },
